"""Construye la página independiente de puertos y condiciones marinas."""
from __future__ import annotations
import html, json
from collections import Counter
from common import DATA_DIR, OUT_DIR, banner

SOURCE = DATA_DIR / "gold" / "ports_marine.json"
PERU = DATA_DIR / "geodata" / "peru.json"

def project(lon, lat): return ((lon + 82) / 14 * 580 + 20, (0 - lat) / 19 * 700 + 10)

def map_paths():
    if not PERU.exists(): return ""
    data=json.loads(PERU.read_text(encoding="utf-8")); paths=[]
    for region in data.get("regions",[]):
        for ring in region.get("rings",[]):
            if len(ring)<3: continue
            coords=[project(lon,lat) for lon,lat in ring]
            path="M"+" L".join(f"{x:.1f},{y:.1f}" for x,y in coords)+" Z"
            paths.append(f'<path d="{path}"><title>{html.escape(region.get("name",""))}</title></path>')
    return "".join(paths)

def main():
    banner("Construyendo página de puertos y mar")
    if not SOURCE.exists(): print("  No existe contrato Gold de puertos"); return 1
    data=json.loads(SOURCE.read_text(encoding="utf-8")); ports=data.get("ports",[])
    counts=Counter(p.get("status","Sin información") for p in ports)
    model=data.get("model") or {}; validation=model.get("validation") or {}
    restriction_metrics=validation.get("restriction") or {}; closure_metrics=validation.get("closure") or {}
    payload=json.dumps(data,ensure_ascii=False).replace("</","<\\/")
    page=f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Puertos y condiciones marinas</title><style>
:root{{--bg:#f5f1e8;--card:#fffdf8;--text:#211d18;--muted:#746a5d;--line:#e7ddca;--yellow:#f4c300;--open:#278052;--partial:#df8a18;--closed:#bd2d2d}}*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--text);font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}}.wrap{{max-width:1240px;margin:auto;padding:22px 20px 60px}}.nav{{display:flex;gap:8px;overflow:auto;margin-bottom:12px}}.nav a{{white-space:nowrap;padding:8px 14px;border:1px solid #d4b75b;border-radius:999px;text-decoration:none;color:#4b351d;background:#fffdf8;font-weight:650}}.nav a.active{{background:var(--yellow)}}
.hero{{background:linear-gradient(135deg,#071c25,#123947 58%,#6a4b19);color:white;border-radius:14px;padding:24px 28px;border-top:5px solid var(--yellow);margin-bottom:16px}}.hero h1{{margin:0 0 5px;font-size:23px}}.hero p{{margin:0;color:#dceff3}}.meta{{margin-top:10px;color:#ffe889;font-size:12px}}.kpis{{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:16px}}.kpi,.card{{background:var(--card);border:1px solid var(--line);border-radius:12px}}.kpi{{padding:13px 16px}}.kpi b{{display:block;font-size:25px}}.kpi span{{font-size:10px;color:var(--muted);text-transform:uppercase}}
.grid{{display:grid;grid-template-columns:minmax(430px,1.25fr) minmax(330px,.75fr);gap:16px}}.card{{padding:18px 20px;margin-bottom:16px}}h2{{font-size:15px;text-transform:uppercase;margin:0 0 12px}}select{{width:100%;padding:9px;border:1px solid #cdbf9f;border-radius:8px;background:white;margin-bottom:9px}}.mapbox{{position:relative;overflow:hidden;border-radius:10px;background:#e7f0f1}}.map{{display:block;width:100%;height:auto;max-height:690px;touch-action:none;cursor:grab}}.map.dragging{{cursor:grabbing}}.regions path{{fill:#eadfc9;stroke:#ad9d82;stroke-width:.7}}.port{{cursor:pointer;stroke-width:3;vector-effect:non-scaling-stroke}}.label{{font-size:10px;font-weight:700;paint-order:stroke;stroke:#fff;stroke-width:3px}}.zoom{{position:absolute;right:10px;top:10px;display:grid;gap:5px}}.zoom button{{width:36px;height:36px;border:1px solid #b9a77e;border-radius:8px;background:#fffdf8;color:#332514;font-size:19px;font-weight:800;box-shadow:0 2px 7px #0002;cursor:pointer}}.timeline{{margin:13px 0 4px;padding:12px 14px;background:#f5f8f8;border:1px solid #d5e3e5;border-radius:10px}}.timeline-head{{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:7px}}.timeline-head b{{font-size:14px}}.timeline input{{width:100%;accent-color:#d49f00}}.timeline-ends{{display:flex;justify-content:space-between;font-size:10px;color:var(--muted)}}.mode{{font-size:10px;text-transform:uppercase;font-weight:800;padding:3px 8px;border-radius:999px;background:#123947;color:white}}.mode.projected{{background:#7b4d12}}.pill{{display:inline-block;color:white;padding:3px 8px;border-radius:999px;font-size:11px;font-weight:750}}.open,.low{{background:#278052}}.partial{{background:#df8a18}}.closed,.very-high{{background:#bd2d2d}}.medium{{background:#d19700}}.high{{background:#df6b24}}.detail{{padding:12px;background:#f5f8f8;border-left:4px solid #1d778e;margin-top:10px}}table{{width:100%;border-collapse:collapse;font-size:12px}}th,td{{padding:8px;border-bottom:1px solid var(--line);text-align:left;white-space:nowrap}}th{{font-size:10px;text-transform:uppercase;background:#faf5e8}}td.num{{text-align:right}}.tablewrap{{overflow:auto;max-height:570px}}.note{{font-size:12px;color:#5c5145}}@media(max-width:880px){{.grid{{grid-template-columns:1fr}}.kpis{{grid-template-columns:1fr 1fr}}.wrap{{padding:12px 10px 40px}}}}</style></head><body><div class="wrap">
<nav class="nav"><a href="index.html">Clima y riesgo</a><a href="precios.html">Precios SISAP</a><a href="abastecimiento.html">Riesgo de abastecimiento</a><a class="active" href="puertos.html">Puertos y mar</a></nav>
<header class="hero"><h1>Estado de puertos y condiciones marinas</h1><p>Estado oficial DICAPI y vigilancia de oleaje y viento para los próximos 15 días.</p><div class="meta">Actualizado {html.escape(data.get("generated_at","—"))} · Oleaje ECMWF WAM / GFS Wave · Viento ECMWF IFS / GFS / ICON</div></header>
<div class="kpis"><div class="kpi"><span>Puertos marítimos</span><b>{len(ports)}</b></div><div class="kpi"><span>Abiertos</span><b>{counts.get("Puerto Abierto",0)}</b></div><div class="kpi"><span>Parcialmente cerrados</span><b>{counts.get("Puerto Parcialmente Cerrado",0)}</b></div><div class="kpi"><span>Cerrados</span><b>{counts.get("Puerto Cerrado",0)}</b></div></div>
<div class="grid"><section><div class="card"><h2>Mapa operativo y proyección</h2><select id="captaincy"><option value="">Todas las capitanías</option></select><div class="timeline"><div class="timeline-head"><b id="timelineDate"></b><span id="timelineMode" class="mode"></span></div><input id="day" type="range" min="0" max="14" step="1" value="0" aria-label="Día del pronóstico"><div class="timeline-ends"><span>Hoy · estado real</span><span>+14 días · proyección</span></div><div id="timelineSummary" class="note"></div></div><div class="mapbox"><svg id="map" class="map" viewBox="0 0 620 730" aria-label="Mapa de puertos marítimos con zoom"><g class="regions">{map_paths()}</g><g id="markers"></g></svg><div class="zoom"><button id="zoomIn" title="Acercar" aria-label="Acercar">+</button><button id="zoomOut" title="Alejar" aria-label="Alejar">−</button><button id="zoomReset" title="Restablecer mapa" aria-label="Restablecer mapa">⌂</button></div></div><p class="note">Usa +/−, la rueda o pellizco para hacer zoom; arrastra para desplazarte. Hoy se muestra el estado oficial DICAPI. Los días futuros muestran una proyección.</p></div></section><aside><div class="card"><h2>Puerto seleccionado</h2><select id="port"></select><div id="detail" class="detail"></div></div><div class="card"><h2>Modelo histórico de cierre</h2><p class="note"><b>Regresión logística regularizada</b> entrenada con estados DICAPI, oleaje Copernicus y viento histórico. Entrenamiento {html.escape(str(model.get("training_period",{}).get("from","—")))}–{html.escape(str(model.get("training_period",{}).get("to","—")))}; validación temporal {html.escape(str(model.get("validation_period",{}).get("from","—")))}–{html.escape(str(model.get("validation_period",{}).get("to","—")))}. AUC restricción <b>{restriction_metrics.get("auc","—")}</b>, AUC cierre <b>{closure_metrics.get("auc","—")}</b>. La probabilidad es una señal estadística y <b>no sustituye la decisión oficial de DICAPI</b>.</p></div></aside></div>
<div class="card"><h2>Pronóstico diario multimodelo</h2><div class="tablewrap"><table><thead><tr><th>Fecha</th><th>Tipo</th><th>Ola ECMWF</th><th>Ola GFS</th><th>Ráfaga ECMWF</th><th>Ráfaga GFS</th><th>Ráfaga ICON</th><th>Señal</th></tr></thead><tbody id="forecast"></tbody></table></div></div>
<div class="card"><h2>Estado oficial DICAPI</h2><div class="tablewrap"><table><thead><tr><th>Puerto</th><th>Capitanía</th><th>Estado</th><th>Publicación</th><th>Resolución</th></tr></thead><tbody id="ports"></tbody></table></div></div></div>
<script>const DATA={payload};const statusColor=s=>s.includes('Parcial')?'#df8a18':s.includes('Cerrado')?'#bd2d2d':'#278052';const statusClass=s=>s.includes('Parcial')?'partial':s.includes('Cerrado')?'closed':'open';const levelColor=s=>s==='Muy alto'?'#bd2d2d':s==='Alto'?'#df6b24':s==='Medio'?'#d19700':'#278052';function xy(lon,lat){{return[(lon+82)/14*580+20,(0-lat)/19*700+10]}}function maxv(a){{return Math.max(0,...a.filter(x=>x!=null))}}function marineDay(p,i){{const w=(DATA.waves[p.id]||[])[i],v=(DATA.wind[p.id]||[])[i],prediction=(DATA.predictions?.[p.id]||[])[i];const wave=maxv(Object.values(w?.models||{{}}).map(x=>x.wave_height_max));const gust=maxv(Object.values(v?.models||{{}}).map(x=>x.wind_gusts_10m_max));const heuristic=.55*Math.min(wave/3,1)+.45*Math.min(gust/20,1);const signal=prediction?.signal||(heuristic>=.55?'Posible cierre':heuristic>=.38?'Posible restricción':heuristic>=.2?'Vigilancia':'Operación probable');const level=signal==='Posible cierre'?'Muy alto':signal==='Posible restricción'?'Alto':signal==='Vigilancia'?'Medio':'Bajo';return{{wave,gust,score:heuristic,level,signal,restriction:prediction?.restriction_probability,closure:prediction?.closure_probability,model:!!prediction}}}}function levelClass(s){{return s==='Muy alto'?'very-high':s.toLowerCase()}}
const cap=document.getElementById('captaincy'),portSel=document.getElementById('port');[...new Set(DATA.ports.map(p=>p.captaincy))].sort().forEach(x=>cap.add(new Option(x,x)));function filtered(){{return DATA.ports.filter(p=>!cap.value||p.captaincy===cap.value)}}function fillPorts(){{const old=portSel.value;portSel.innerHTML='';filtered().forEach(p=>portSel.add(new Option(p.name,p.id)));if([...portSel.options].some(o=>o.value===old))portSel.value=old;renderMap();renderPort()}}
function currentDay(){{return Number(document.getElementById('day').value)}}function forecastDate(i){{return (DATA.waves[DATA.ports[0]?.id]||[])[i]?.date||''}}function renderTimeline(){{const i=currentDay(),date=forecastDate(i),mode=document.getElementById('timelineMode');document.getElementById('timelineDate').textContent=new Date(date+'T12:00:00').toLocaleDateString('es-PE',{{weekday:'long',day:'numeric',month:'long'}});mode.textContent=i===0?'Estado oficial hoy':'Proyección día +'+i;mode.className='mode'+(i?' projected':'');const all=filtered().map(p=>marineDay(p,i));const close=all.filter(x=>x.level==='Muy alto').length,restrict=all.filter(x=>x.level==='Alto').length;document.getElementById('timelineSummary').innerHTML=i===0?`DICAPI real: ${{filtered().filter(p=>p.status.includes('Cerrado')).length}} cerrados · Señal marina: ${{close}} en posible cierre.`:`Proyección preventiva: <b>${{close}}</b> en posible cierre y <b>${{restrict}}</b> en posible restricción.`}}
function renderMap(){{const i=currentDay(),g=document.getElementById('markers');g.innerHTML='';filtered().forEach(p=>{{const[x,y]=xy(p.lon,p.lat),m=marineDay(p,i),c=document.createElementNS('http://www.w3.org/2000/svg','circle');c.setAttribute('cx',x);c.setAttribute('cy',y);c.setAttribute('r',p.id===portSel.value?7:4.5);c.setAttribute('fill',i===0?statusColor(p.status):levelColor(m.level));c.setAttribute('stroke',i===0?levelColor(m.level):'#fff');c.setAttribute('class','port');c.onclick=()=>{{portSel.value=p.id;renderMap();renderPort()}};const title=document.createElementNS('http://www.w3.org/2000/svg','title');title.textContent=i===0?`${{p.name}}: ${{p.status}} · ${{m.signal}}`:`${{p.name}}: ${{m.signal}}`;c.appendChild(title);g.appendChild(c);if(p.id===portSel.value){{const t=document.createElementNS('http://www.w3.org/2000/svg','text');t.setAttribute('x',x+10);t.setAttribute('y',y+3);t.setAttribute('class','label');t.textContent=p.name;g.appendChild(t)}}}});renderTimeline()}}function fmtDate(x){{return x?new Date(x).toLocaleString('es-PE',{{dateStyle:'short',timeStyle:'short'}}):'—'}}function val(d,m,k){{return d?.models?.[m]?.[k]}}
function renderPort(){{const p=DATA.ports.find(x=>x.id===portSel.value)||filtered()[0];if(!p)return;portSel.value=p.id;const i=currentDay(),m=marineDay(p,i),date=forecastDate(i),reading=i===0?`Estado oficial: <span class="pill ${{statusClass(p.status)}}">${{p.status}}</span>`:`Proyección: <span class="pill ${{levelClass(m.level)}}">${{m.signal}}</span>`,prob=m.model?`<br>Prob. restricción <b>${{Math.round(m.restriction*100)}}%</b> · Prob. cierre total <b>${{Math.round(m.closure*100)}}%</b>`:`<br>Índice heurístico ${{Math.round(m.score*100)}}/100`;document.getElementById('detail').innerHTML=`<b>${{p.name}}</b><br>${{p.captaincy}} · ${{date}}<br>${{reading}}${{prob}}<br>Ola máx. ${{m.wave.toFixed(2)}} m · ráfaga máx. ${{m.gust.toFixed(1)}} m/s${{i===0?`<br>Publicación DICAPI: ${{fmtDate(p.publication_date)}}`:''}}`;const waves=DATA.waves[p.id]||[],winds=DATA.wind[p.id]||[];document.getElementById('forecast').innerHTML=waves.map((d,j)=>{{const wd=winds[j],x=marineDay(p,j),type=j===0?'Real + modelo':'Proyección',signal=x.model?`${{x.signal}} (${{Math.round(x.closure*100)}}% cierre)`:x.signal;return`<tr><td>${{d.date}}</td><td>${{type}}</td><td>${{val(d,'ecmwf_wam025','wave_height_max')??'—'}} m</td><td>${{val(d,'ncep_gfswave025','wave_height_max')??'—'}} m</td><td>${{val(wd,'ecmwf_ifs025','wind_gusts_10m_max')??'—'}} m/s</td><td>${{val(wd,'gfs_seamless','wind_gusts_10m_max')??'—'}} m/s</td><td>${{val(wd,'icon_seamless','wind_gusts_10m_max')??'—'}} m/s</td><td><span class="pill ${{levelClass(x.level)}}">${{signal}}</span></td></tr>`}}).join('');renderMap()}}
function renderTable(){{document.getElementById('ports').innerHTML=DATA.ports.map(p=>`<tr><td><b>${{p.name}}</b></td><td>${{p.captaincy}}</td><td><span class="pill ${{statusClass(p.status)}}">${{p.status}}</span></td><td>${{fmtDate(p.publication_date)}}</td><td>${{p.resolution_url?`<a href="${{p.resolution_url}}" target="_blank">${{p.resolution||'Ver'}}</a>`:(p.resolution||'—')}}</td></tr>`).join('')}}
const svg=document.getElementById('map'),base={{x:0,y:0,w:620,h:730}},view={{...base}};function setView(){{svg.setAttribute('viewBox',`${{view.x}} ${{view.y}} ${{view.w}} ${{view.h}}`)}}function zoom(f){{const nw=Math.max(90,Math.min(620,view.w*f)),nh=nw*730/620;view.x+=(view.w-nw)/2;view.y+=(view.h-nh)/2;view.w=nw;view.h=nh;setView()}}document.getElementById('zoomIn').onclick=()=>zoom(.72);document.getElementById('zoomOut').onclick=()=>zoom(1.38);document.getElementById('zoomReset').onclick=()=>{{view={{...base}};setView()}};svg.addEventListener('wheel',e=>{{e.preventDefault();zoom(e.deltaY<0?.82:1.22)}},{{passive:false}});let drag=null;svg.addEventListener('pointerdown',e=>{{drag={{x:e.clientX,y:e.clientY,vx:view.x,vy:view.y}};svg.classList.add('dragging');svg.setPointerCapture(e.pointerId)}});svg.addEventListener('pointermove',e=>{{if(!drag)return;view.x=drag.vx-(e.clientX-drag.x)*view.w/svg.clientWidth;view.y=drag.vy-(e.clientY-drag.y)*view.h/svg.clientHeight;setView()}});svg.addEventListener('pointerup',()=>{{drag=null;svg.classList.remove('dragging')}});
cap.onchange=fillPorts;portSel.onchange=renderPort;document.getElementById('day').oninput=()=>{{renderPort()}};renderTable();fillPorts();</script></body></html>'''
    OUT_DIR.mkdir(parents=True,exist_ok=True); target=OUT_DIR/"puertos.html"; target.write_text(page,encoding="utf-8"); print(f"  -> {target} ({len(ports)} puertos)"); return 0

if __name__=="__main__": raise SystemExit(main())
